<template><div class="page-container"><el-card><template #header>学生查看选题规则</template><el-form label-width="130px"><el-form-item label="选题周期"><el-select v-model="cycleId" @change="load"><el-option v-for="c in cycles" :key="c.id" :label="c.name" :value="c.id" /></el-select></el-form-item><el-form-item label="查看范围"><el-radio-group v-model="mode"><el-radio value="same_major">仅本专业（默认）</el-radio><el-radio value="all">全部专业</el-radio><el-radio value="matrix">按专业授权</el-radio></el-radio-group></el-form-item><el-form-item v-if="mode === 'matrix'" label="授权矩阵"><el-input v-model="matrixText" type="textarea" :rows="5" placeholder="每行：学生专业代码=可查看的专业代码，多个用逗号分隔" /></el-form-item><el-button type="primary" :disabled="!cycleId" @click="save">保存规则</el-button></el-form></el-card></div></template>
<script setup lang="ts">
import { ref, onMounted } from 'vue'; import { cycleApi, topicAccessApi } from '../../api'; import { ElMessage } from 'element-plus'
const cycles = ref<any[]>([]), cycleId = ref(''), mode = ref('same_major'), matrixText = ref('')
async function load() { if (!cycleId.value) return; const r:any = await topicAccessApi.get(cycleId.value); mode.value = r.data?.mode || 'same_major'; matrixText.value = Object.entries(r.data?.matrix || {}).map(([k,v]) => `${k}=${(v as string[]).join(',')}`).join('\n') }
async function save() { const matrix:any = {}; matrixText.value.split('\n').forEach(line => { const [k,v] = line.split('='); if (k?.trim()) matrix[k.trim()] = (v || '').split(',').map(x => x.trim()).filter(Boolean) }); await topicAccessApi.save(cycleId.value, { mode: mode.value, matrix }); ElMessage.success('规则已保存') }
onMounted(async () => { const r:any = await cycleApi.getAll(); cycles.value = Array.isArray(r.data) ? r.data : []; cycleId.value = cycles.value[0]?.id || ''; await load() })
</script>
